#!/usr/bin/env python3
import argparse
import hashlib
import json
import os
import platform
import re
import shutil
import signal
import sqlite3
import statistics
import subprocess
import sys
import tempfile
import threading
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
WORKTREE = HERE.parents[1]
CORPUS_SOURCE = WORKTREE / "target" / "receiver-reference-reliability" / "benchmark" / "corpora"
BASELINE_BINARY = HERE / "before-code-kb"
SETUP_PATH = HERE / "measure-setup.json"
PLAN_PATH = HERE / "measure-plan.json"
RUNS_PATH = HERE / "paired-run-copies"
RESULTS_PATH = HERE / "paired-results"
TMP_ROOT = HERE / "tmp"
SAMPLES = 5
REQUEST_TIMEOUT_SECONDS = 120
READINESS_TIMEOUT_SECONDS = 300
INDEXING_NOTICE = re.compile(r"^Indexing .+ started; call again in a few seconds\.$")
CAPTURED_RESPONSES: list[dict[str, Any]] = []

TMP_ROOT.mkdir(parents=True, exist_ok=True)
os.environ["TMPDIR"] = str(TMP_ROOT)
tempfile.tempdir = str(TMP_ROOT)
sys.path.insert(0, str(WORKTREE / "scripts"))
import benchmark_quality
from benchmark_quality import PersistentMcpClient, percentile

ORIGINAL_MCP_RESULT = benchmark_quality.mcp_result


class RequestTimeout(TimeoutError):
    pass


def capture_mcp_result(response: dict[str, Any], request_id: int, operation: str) -> dict[str, Any]:
    CAPTURED_RESPONSES.append(response)
    return ORIGINAL_MCP_RESULT(response, request_id, operation)


benchmark_quality.mcp_result = capture_mcp_result


class Journal:
    def __init__(self, path: Path):
        self.path = path
        self.stream = path.open("x", encoding="utf-8")

    def write(self, event: str, **fields: Any) -> None:
        record = {"event": event, "at": datetime.now(timezone.utc).isoformat(), **fields}
        self.stream.write(json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n")
        self.stream.flush()
        os.fsync(self.stream.fileno())
        progress = {key: record[key] for key in (
            "event", "side", "corpus", "workload_id", "phase", "sample", "status",
            "elapsed_ms", "index_artifact_bytes", "result_path", "destination",
        ) if key in record}
        outcome = record.get("outcome")
        if isinstance(outcome, dict):
            progress.update({key: outcome[key] for key in ("status", "elapsed_ms", "result_count") if key in outcome})
        print(json.dumps(progress, ensure_ascii=False, separators=(",", ":")), flush=True)

    def close(self) -> None:
        self.stream.close()


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(8 * 1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def git_state(path: Path) -> dict[str, Any]:
    def git(*args: str) -> str:
        return subprocess.run(
            ["git", "-C", str(path), *args], check=True, capture_output=True, text=True
        ).stdout.strip()

    porcelain = git("status", "--porcelain")
    return {
        "path": str(path),
        "branch": git("branch", "--show-current"),
        "head": git("rev-parse", "HEAD"),
        "status_short_branch": git("status", "--short", "--branch"),
        "dirty": bool(porcelain),
        "porcelain": porcelain.splitlines(),
    }


def result_text(result: dict[str, Any]) -> str:
    return "\n".join(
        block.get("text", "")
        for block in result.get("content", [])
        if isinstance(block, dict) and isinstance(block.get("text"), str)
    )


def replace_root(value: Any, root: str) -> Any:
    if isinstance(value, str):
        return value.replace(root, "<project_root>")
    if isinstance(value, list):
        return [replace_root(item, root) for item in value]
    if isinstance(value, dict):
        return {key: replace_root(item, root) for key, item in value.items()}
    return value


def blast_section_counts(text: str) -> dict[str, int]:
    patterns = {
        "likely_tests": r"^### Likely Tests to Run \((\d+) returned\)$",
        "downstream_impact": r"^### Downstream Impact \((\d+) returned\)$",
    }
    counts = {}
    for name, pattern in patterns.items():
        match = re.search(pattern, text, re.MULTILINE)
        if match:
            counts[name] = int(match.group(1))
    return counts


def result_count(result: dict[str, Any], text: str) -> int | None:
    blast_counts = blast_section_counts(text)
    if blast_counts:
        return sum(blast_counts.values())
    match = re.search(r"^(?:Callers|Callees) of .+?\((\d+) found\):$", text, re.MULTILINE | re.IGNORECASE)
    if match:
        return int(match.group(1))
    structured = result.get("structuredContent")
    if isinstance(structured, dict):
        for key in ("references", "results", "symbols", "rows", "tests", "callers", "callees", "matches", "facts"):
            if isinstance(structured.get(key), list):
                return len(structured[key])
    match = re.search(r"\b(?:Found|Showing)\s+(\d+)\s+(?:references?|symbols?|rows?|tests?|files?|results?)\b", text, re.IGNORECASE)
    return int(match.group(1)) if match else None


def summarize_response(response: dict[str, Any] | None, root: str) -> dict[str, Any]:
    if response is None:
        return {"output_sha256": None, "result_count": None, "section_counts": {}, "text_line_count": None}
    result = response.get("result", {})
    text = result_text(result) if isinstance(result, dict) else ""
    normalized = replace_root(result if "error" not in response else {"error": response["error"]}, root)
    encoded = json.dumps(normalized, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    return {
        "output_sha256": hashlib.sha256(encoded).hexdigest(),
        "result_count": result_count(result, text) if isinstance(result, dict) else None,
        "section_counts": blast_section_counts(text),
        "text_line_count": sum(bool(line.strip()) for line in text.splitlines()),
    }


def index_state(root: Path) -> dict[str, Any]:
    database = root / ".code-kb" / "artifact.db"
    connection = sqlite3.connect(f"file:{database}?mode=ro", uri=True)
    try:
        tables = {row[0] for row in connection.execute("select name from sqlite_master where type='table'")}
        metadata = dict(connection.execute("select key, value from artifact_metadata")) if "artifact_metadata" in tables else {}
        indexes = [
            {"name": name, "table": table, "sql": sql}
            for name, table, sql in connection.execute(
                "select name, tbl_name, sql from sqlite_master where type='index' order by name"
            )
        ]
        page_size = connection.execute("pragma page_size").fetchone()[0]
        page_count = connection.execute("pragma page_count").fetchone()[0]
        journal_mode = connection.execute("pragma journal_mode").fetchone()[0]
    finally:
        connection.close()
    files = {}
    for suffix in ("", "-wal", "-shm", ".rebuild"):
        path = Path(str(database) + suffix)
        if path.is_file():
            files[path.name] = path.stat().st_size
    return {
        "database_path": str(database),
        "index_artifact_files": files,
        "index_artifact_bytes": sum(files.values()),
        "logical_database_bytes": page_size * page_count,
        "page_size": page_size,
        "page_count": page_count,
        "journal_mode": journal_mode,
        "artifact_schema_metadata": {
            key: metadata.get(key)
            for key in ("schema_version", "sqlite_schema_version", "extract_contract_version", "binary_version", "index_level", "fts_rule", "root_path")
        },
        "indexes": indexes,
    }


def make_index_copy(source_root: Path, destination: Path, source_index_sha256: str) -> dict[str, Any]:
    source_db = source_root / ".code-kb" / "artifact.db"
    if not source_db.is_file():
        raise FileNotFoundError(source_db)
    if destination.exists():
        raise FileExistsError(destination)

    def ignore(directory: str, names: list[str]) -> set[str]:
        return {name for name in names if name in {".code-kb", ".git"}} if Path(directory) == source_root else ({".git"} if ".git" in names else set())

    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(source_root, destination, ignore=ignore)
    destination_db = destination / ".code-kb" / "artifact.db"
    destination_db.parent.mkdir(parents=True, exist_ok=True)
    (destination / ".code-kb" / ".gitignore").write_text("*\n", encoding="utf-8")
    source = sqlite3.connect(f"file:{source_db}?mode=ro", uri=True)
    target = sqlite3.connect(destination_db)
    try:
        source.backup(target, pages=16384, sleep=0.01)
    finally:
        target.close()
        source.close()
    for suffix in ("-wal", "-shm"):
        sidecar = Path(str(destination_db) + suffix)
        if sidecar.exists():
            sidecar.unlink()
    state = index_state(destination)
    return {
        "root": str(destination),
        "source_root": str(source_root),
        "source_index_sha256": source_index_sha256,
        "index_sha256": sha256(destination_db),
        "index_state_before_sessions": state,
    }


def proc_snapshot(pid: int) -> dict[str, Any] | None:
    root = Path(f"/proc/{pid}")
    try:
        fields = (root / "stat").read_text(encoding="utf-8").rsplit(")", 1)[1].split()
        ticks = os.sysconf("SC_CLK_TCK")
        counters = {
            "at_monotonic": time.monotonic(),
            "user_cpu_seconds": int(fields[11]) / ticks,
            "system_cpu_seconds": int(fields[12]) / ticks,
            "major_faults": int(fields[9]),
            "minor_faults": int(fields[7]),
        }
        counters["io"] = {
            key: int(value)
            for key, value in (line.split(":", 1) for line in (root / "io").read_text(encoding="utf-8").splitlines())
        }
        status = dict(line.split(":", 1) for line in (root / "status").read_text(encoding="utf-8").splitlines())
        counters["rss_kib"] = int(status["VmRSS"].split()[0])
        return counters
    except (FileNotFoundError, PermissionError, ProcessLookupError, KeyError, ValueError, OSError):
        return None


def rss_sampler(pid: int, stop: threading.Event, samples: list[int]) -> None:
    while not stop.wait(0.25):
        try:
            status = Path(f"/proc/{pid}/status").read_text(encoding="utf-8")
            rss_line = next(line for line in status.splitlines() if line.startswith("VmRSS:"))
        except (OSError, StopIteration):
            return
        samples.append(int(rss_line.split()[1]))


def process_delta(before: dict[str, Any] | None, after: dict[str, Any] | None, rss_samples: list[int]) -> dict[str, Any]:
    if before is None or after is None:
        return {"before": before, "after": after, "delta": None, "rss_peak_mib": max(rss_samples) / 1024 if rss_samples else None}
    wall = after["at_monotonic"] - before["at_monotonic"]
    user = after["user_cpu_seconds"] - before["user_cpu_seconds"]
    system = after["system_cpu_seconds"] - before["system_cpu_seconds"]
    io_delta = {
        key: after["io"].get(key, 0) - value
        for key, value in before["io"].items()
    }
    return {
        "before": before,
        "after": after,
        "delta": {
            "observation_seconds": wall,
            "user_cpu_seconds": user,
            "system_cpu_seconds": system,
            "cpu_percent_of_one_core": (user + system) / wall * 100 if wall > 0 else None,
            "io": io_delta,
            "major_faults": after["major_faults"] - before["major_faults"],
            "minor_faults": after["minor_faults"] - before["minor_faults"],
        },
        "rss_peak_mib": max(rss_samples) / 1024 if rss_samples else max(before["rss_kib"], after["rss_kib"]) / 1024,
        "rss_samples": len(rss_samples),
    }


class Session:
    def __init__(self, side: str, binary: Path, root: Path, journal: Journal):
        self.side = side
        self.binary = binary
        self.root = root
        self.journal = journal
        self.client: PersistentMcpClient | None = None
        self.starts: list[dict[str, Any]] = []

    def start(self) -> dict[str, Any]:
        self.journal.write("session_starting", side=self.side, corpus=self.root.name, binary=str(self.binary), root=str(self.root))
        started = time.perf_counter()
        self.client = PersistentMcpClient(str(self.binary), str(self.root))
        spawn_ms = (time.perf_counter() - started) * 1000
        try:
            initialize_ms = self.client.initialize()
        except Exception:
            self.close()
            raise
        record = {
            "side": self.side,
            "binary": str(self.binary),
            "process_spawn_ms": spawn_ms,
            "initialize_ms": initialize_ms,
            "started_at": datetime.now(timezone.utc).isoformat(),
        }
        self.starts.append(record)
        self.journal.write("session_ready", side=self.side, corpus=self.root.name, process_spawn_ms=spawn_ms, initialize_ms=initialize_ms)
        return record

    def close(self) -> None:
        if self.client is not None:
            self.client.close()
            self.client = None

    def memory(self) -> dict[str, float | None] | None:
        if self.client is None or self.client.proc.poll() is not None:
            return None
        values = self.client.get_live_memory()
        return {key: value if value > 0 else None for key, value in values.items()}


def request_with_deadline(session: Session, workload: dict[str, Any], timeout_seconds: float):
    if session.client is None:
        session.start()
    client = session.client
    pid = client.proc.pid
    CAPTURED_RESPONSES.clear()
    def expire(signum, frame):
        raise RequestTimeout(f"request exceeded {timeout_seconds:.0f} seconds")

    previous_handler = signal.signal(signal.SIGALRM, expire)
    previous_timer = signal.setitimer(signal.ITIMER_REAL, timeout_seconds)
    try:
        response, elapsed_ms = client.call_tool(workload["tool"], workload["arguments"])
        return response, elapsed_ms, CAPTURED_RESPONSES[-1] if CAPTURED_RESPONSES else response, None, pid
    except RequestTimeout as exc:
        session.close()
        return None, None, CAPTURED_RESPONSES[-1] if CAPTURED_RESPONSES else None, str(exc), pid
    except Exception as exc:
        raw = CAPTURED_RESPONSES[-1] if CAPTURED_RESPONSES else None
        if client.proc.poll() is not None:
            session.close()
        return None, None, raw, str(exc), pid
    finally:
        signal.setitimer(signal.ITIMER_REAL, *previous_timer)
        signal.signal(signal.SIGALRM, previous_handler)


def request_once(
    session: Session,
    workload: dict[str, Any],
    journal: Journal,
    phase: str,
    sample: int | None = None,
    timeout_seconds: float = REQUEST_TIMEOUT_SECONDS,
    measure_process: bool = False,
) -> dict[str, Any]:
    if session.client is None:
        session.start()
    context = {
        "side": session.side,
        "corpus": session.root.name,
        "workload_id": workload["id"],
        "phase": phase,
        "sample": sample,
        "tool": workload["tool"],
        "arguments": workload["arguments"],
        "timeout_seconds": timeout_seconds,
    }
    journal.write("request_started", **context)
    pid = session.client.proc.pid
    before = proc_snapshot(pid) if measure_process else None
    rss_samples = [before["rss_kib"]] if before else []
    stop = threading.Event()
    sampler = threading.Thread(target=rss_sampler, args=(pid, stop, rss_samples), daemon=True) if measure_process else None
    if sampler:
        sampler.start()
    started = time.perf_counter()
    response, elapsed_ms, raw_response, error, _ = request_with_deadline(session, workload, timeout_seconds)
    if sampler:
        stop.set()
        sampler.join()
    after = proc_snapshot(pid) if measure_process else None
    if elapsed_ms is None:
        elapsed_ms = (time.perf_counter() - started) * 1000
    if error:
        status = "timeout" if error.startswith("request exceeded ") else "error"
    else:
        result = response.get("result", {})
        text = result_text(result) if isinstance(result, dict) else ""
        status = "indexing" if INDEXING_NOTICE.match(text.strip()) else "completed"
    summary = summarize_response(raw_response, str(session.root))
    outcome = {
        "status": status,
        "elapsed_ms": elapsed_ms,
        "error": error,
        **summary,
        "raw_response": raw_response,
    }
    if measure_process:
        outcome["process"] = process_delta(before, after, rss_samples)
    journal.write("request_outcome", **context, outcome=outcome)
    return outcome


def await_ready(
    session: Session,
    workload: dict[str, Any],
    journal: Journal,
    phase: str,
    sample: int | None = None,
) -> dict[str, Any]:
    deadline = time.monotonic() + READINESS_TIMEOUT_SECONDS
    attempts = []
    while time.monotonic() < deadline:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        outcome = request_once(
            session,
            workload,
            journal,
            phase,
            sample,
            min(REQUEST_TIMEOUT_SECONDS, remaining),
        )
        attempts.append(outcome)
        if outcome["status"] == "indexing":
            time.sleep(min(0.25, max(0, deadline - time.monotonic())))
            continue
        if outcome["status"] == "timeout":
            if session.client is None:
                try:
                    session.start()
                except Exception as exc:
                    attempts.append({"status": "restart_error", "error": str(exc)})
                    break
            continue
        return {"first_response": attempts[0], "ready_response": outcome, "attempts": attempts}
    status = attempts[-1]["status"] if attempts else "readiness_timeout"
    if status in {"indexing", "timeout"}:
        status = "readiness_timeout"
    return {
        "first_response": attempts[0] if attempts else None,
        "ready_response": {"status": status, "elapsed_ms": None},
        "attempts": attempts,
    }


def paired_copy_set(run_id: str, setup: dict[str, Any], journal: Journal) -> dict[str, Any]:
    copies: dict[str, Any] = {}
    for corpus in ("flask", "hermes"):
        source = Path(setup["corpora"][corpus]["frozen_export_root"])
        expected = setup["corpora"][corpus]["source_index"]
        source_db = source / ".code-kb" / "artifact.db"
        source_state = index_state(source)
        expected_state = expected["index_state_before_copying"]
        if any(source_state[key] != expected_state[key] for key in ("indexes", "page_size", "page_count", "journal_mode")):
            raise RuntimeError(f"{corpus} source index metadata changed since measure-setup.json was captured")
        if source_state["artifact_schema_metadata"] != expected["artifact_schema_metadata"]:
            raise RuntimeError(f"{corpus} source artifact metadata changed since measure-setup.json was captured")
        source_hash = sha256(source_db)
        if source_hash != expected["sha256"]:
            raise RuntimeError(f"{corpus} source index changed since measure-setup.json was captured")
        copies[corpus] = {}
        for side in ("baseline", "candidate"):
            destination = RUNS_PATH / run_id / side / corpus
            journal.write("corpus_copy_started", corpus=corpus, side=side, source=str(source), destination=str(destination))
            copied = make_index_copy(source, destination, source_hash)
            if copied["source_index_sha256"] != expected["sha256"]:
                raise RuntimeError(f"{corpus} source index changed since measure-setup.json was captured")
            copied["counts"] = expected["counts"]
            copied["index_state_before_sessions"]["counts"] = expected["counts"]
            copies[corpus][side] = copied
        baseline = copies[corpus]["baseline"]
        candidate = copies[corpus]["candidate"]
        if baseline["index_sha256"] != candidate["index_sha256"]:
            raise RuntimeError(f"{corpus} baseline/candidate index copies differ before server startup")
        journal.write(
            "corpus_copies_ready",
            corpus=corpus,
            initial_index_sha256=baseline["index_sha256"],
            counts=baseline["counts"],
        )
    return copies


def index_changes(before: dict[str, Any], after: dict[str, Any]) -> dict[str, Any]:
    before_by_name = {row["name"]: row for row in before["indexes"]}
    after_by_name = {row["name"]: row for row in after["indexes"]}
    return {
        "installed": [after_by_name[name] for name in sorted(after_by_name.keys() - before_by_name.keys())],
        "removed": [before_by_name[name] for name in sorted(before_by_name.keys() - after_by_name.keys())],
        "changed": [
            {"before": before_by_name[name], "after": after_by_name[name]}
            for name in sorted(before_by_name.keys() & after_by_name.keys())
            if before_by_name[name] != after_by_name[name]
        ],
        "index_artifact_bytes_before": before["index_artifact_bytes"],
        "index_artifact_bytes_after": after["index_artifact_bytes"],
        "index_artifact_bytes_delta": after["index_artifact_bytes"] - before["index_artifact_bytes"],
        "logical_database_bytes_before": before["logical_database_bytes"],
        "logical_database_bytes_after": after["logical_database_bytes"],
        "logical_database_bytes_delta": after["logical_database_bytes"] - before["logical_database_bytes"],
    }


def summarize_samples(samples: list[dict[str, Any]]) -> dict[str, Any]:
    values = [row["elapsed_ms"] for row in samples if row.get("elapsed_ms") is not None]
    completed = [row["elapsed_ms"] for row in samples if row["status"] == "completed" and row.get("elapsed_ms") is not None]
    return {
        "sample_count": len(samples),
        "completed_count": sum(row["status"] == "completed" for row in samples),
        "error_count": sum(row["status"] == "error" for row in samples),
        "timeout_count": sum(row["status"] == "timeout" for row in samples),
        "not_run_count": sum(row["status"].startswith("not_run") for row in samples),
        "all_outcome_median_ms": statistics.median(values) if values else None,
        "all_outcome_p95_ms": percentile(values, 0.95) if len(values) == SAMPLES else None,
        "completed_median_ms": statistics.median(completed) if completed else None,
        "completed_p95_ms": percentile(completed, 0.95) if completed else None,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--candidate-binary", required=True, type=Path)
    parser.add_argument("--run-id", required=True)
    options = parser.parse_args()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,79}", options.run_id):
        parser.error("run-id must use 1-80 letters, digits, dots, underscores, or hyphens")
    candidate_binary = options.candidate_binary.resolve()
    if not candidate_binary.is_file():
        parser.error(f"candidate binary is missing: {candidate_binary}")
    setup = json.loads(SETUP_PATH.read_text(encoding="utf-8"))
    plan = json.loads(PLAN_PATH.read_text(encoding="utf-8"))
    if not BASELINE_BINARY.is_file() or sha256(BASELINE_BINARY) != setup["baseline"]["sha256"]:
        parser.error("before-code-kb hash no longer matches measure-setup.json")
    candidate_version = subprocess.run([str(candidate_binary), "--version"], check=True, capture_output=True, text=True).stdout.strip()
    baseline_version = subprocess.run([str(BASELINE_BINARY), "--version"], check=True, capture_output=True, text=True).stdout.strip()
    output_path = RESULTS_PATH / f"{options.run_id}.json"
    journal_path = RESULTS_PATH / f"{options.run_id}.events.jsonl"
    copy_path = RUNS_PATH / options.run_id
    if output_path.exists() or journal_path.exists() or output_path.with_suffix(".json.tmp").exists() or copy_path.exists():
        parser.error(f"run id already exists: {options.run_id}")
    RESULTS_PATH.mkdir(parents=True, exist_ok=True)
    journal = Journal(journal_path)
    output: dict[str, Any] = {
        "run_id": options.run_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "setup_path": str(SETUP_PATH),
        "plan_path": str(PLAN_PATH),
        "checkpoint_journal": str(journal_path),
        "task_worktree": git_state(WORKTREE),
        "settings": {
            "samples_per_workload_and_binary": SAMPLES,
            "request_timeout_seconds": REQUEST_TIMEOUT_SECONDS,
            "readiness_timeout_seconds": READINESS_TIMEOUT_SECONDS,
            "warmups_per_workload_and_binary": 1,
            "tmpdir": str(TMP_ROOT),
        },
        "binaries": {
            "baseline": {**setup["baseline"], "version": baseline_version},
            "candidate": {
                "path": str(candidate_binary),
                "sha256": sha256(candidate_binary),
                "version": candidate_version,
            },
        },
        "corpus_copies": {},
        "measurements": [],
    }
    journal.write(
        "run_started",
        run_id=options.run_id,
        result_path=str(output_path),
        candidate_binary=output["binaries"]["candidate"],
        settings=output["settings"],
        workload_count=len(plan["workloads"]),
    )
    sessions: dict[tuple[str, str], Session] = {}
    try:
        copies = paired_copy_set(options.run_id, setup, journal)
        output["corpus_copies"] = copies
        sides = {"baseline": BASELINE_BINARY, "candidate": candidate_binary}
        workload_order = {item["id"]: index for index, item in enumerate(plan["workloads"])}
        for corpus_index, corpus in enumerate(("flask", "hermes")):
            start_order = ["baseline", "candidate"] if corpus_index == 0 else ["candidate", "baseline"]
            output.setdefault("session_order", []).append({"corpus": corpus, "order": start_order})
            for side in start_order:
                session = Session(side, sides[side], Path(copies[corpus][side]["root"]), journal)
                sessions[(corpus, side)] = session
                session.start()
                after_start = index_state(session.root)
                copies[corpus][side]["index_state_after_session_start"] = after_start
                copies[corpus][side]["index_changes_after_session_start"] = index_changes(
                    copies[corpus][side]["index_state_before_sessions"], after_start
                )
                journal.write(
                    "index_state_after_session_start",
                    side=side,
                    corpus=corpus,
                    index_artifact_bytes=after_start["index_artifact_bytes"],
                    installed_indexes=copies[corpus][side]["index_changes_after_session_start"]["installed"],
                )

            workloads = [item for item in plan["workloads"] if item["corpus"] == corpus]
            for local_index, workload in enumerate(workloads):
                global_index = workload_order[workload["id"]]
                prepare_order = ["baseline", "candidate"] if global_index % 2 == 0 else ["candidate", "baseline"]
                per_side = {}
                for side in prepare_order:
                    session = sessions[(corpus, side)]
                    if session.client is None:
                        session.start()
                    first = await_ready(session, workload, journal, "first_response")
                    warmup = await_ready(session, workload, journal, "warmup")
                    per_side[side] = {
                        "workload_id": workload["id"],
                        "corpus": corpus,
                        "tool": workload["tool"],
                        "arguments": workload["arguments"],
                        "first_response": first["first_response"],
                        "first_readiness_attempts": first["attempts"],
                        "first_ready_response": first["ready_response"],
                        "warmup": warmup,
                        "memory_before": session.memory(),
                        "session_starts": session.starts,
                        "samples": [],
                    }
                    journal.write(
                        "workload_warmed",
                        side=side,
                        corpus=corpus,
                        workload_id=workload["id"],
                        first_status=first["ready_response"]["status"],
                        warmup_status=warmup["ready_response"]["status"],
                        memory=per_side[side]["memory_before"],
                    )

                for sample_number in range(1, SAMPLES + 1):
                    pair_order = ["baseline", "candidate"] if (sample_number + global_index) % 2 == 0 else ["candidate", "baseline"]
                    output.setdefault("paired_sample_order", []).append(
                        {"workload_id": workload["id"], "sample": sample_number, "order": pair_order}
                    )
                    for side in pair_order:
                        session = sessions[(corpus, side)]
                        record = per_side[side]
                        readiness_attempts = []
                        if session.client is None:
                            recovery = await_ready(session, workload, journal, "recovery", sample_number)
                            readiness_attempts.extend(recovery["attempts"])
                            if session.client is None:
                                sample = {
                                    "sample": sample_number,
                                    "status": "not_run_session_unavailable",
                                    "elapsed_ms": None,
                                    "readiness_attempts": readiness_attempts,
                                }
                                record["samples"].append(sample)
                                journal.write("sample_checkpoint", side=side, workload_id=workload["id"], sample=sample_number, outcome=sample)
                                continue
                        response = request_once(session, workload, journal, "measured", sample_number, measure_process=True)
                        retry_response = None
                        if response["status"] == "indexing":
                            readiness = await_ready(session, workload, journal, "measured_readiness", sample_number)
                            readiness_attempts.extend(readiness["attempts"])
                            if readiness["ready_response"]["status"] == "completed" and session.client is not None:
                                retry_response = request_once(session, workload, journal, "measured_retry", sample_number, measure_process=True)
                                response = retry_response
                            else:
                                response = {"status": "not_run_readiness_timeout", "elapsed_ms": None}
                        sample = {
                            "sample": sample_number,
                            "status": response["status"],
                            "elapsed_ms": response.get("elapsed_ms"),
                            "response": response,
                            "retry_response": retry_response,
                            "readiness_attempts": readiness_attempts,
                        }
                        record["samples"].append(sample)
                        journal.write("sample_checkpoint", side=side, workload_id=workload["id"], sample=sample_number, outcome=sample)
                for side in ("baseline", "candidate"):
                    session = sessions[(corpus, side)]
                    record = per_side[side]
                    record["memory_after"] = session.memory()
                    record["summary"] = summarize_samples(record["samples"])
                    output["measurements"].append(record)
        for session in sessions.values():
            session.close()
        for corpus in ("flask", "hermes"):
            for side in ("baseline", "candidate"):
                copied = copies[corpus][side]
                final_state = index_state(Path(copied["root"]))
                copied["index_state_after_measurements"] = final_state
                copied["index_changes_after_measurements"] = index_changes(
                    copied["index_state_before_sessions"], final_state
                )
                journal.write(
                    "index_state_after_measurements",
                    side=side,
                    corpus=corpus,
                    index_artifact_bytes=final_state["index_artifact_bytes"],
                    installed_indexes=copied["index_changes_after_measurements"]["installed"],
                )
        temporary = output_path.with_suffix(".json.tmp")
        temporary.write_text(json.dumps(output, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        temporary.replace(output_path)
        journal.write("run_complete", result_path=str(output_path))
    finally:
        for session in sessions.values():
            session.close()
        journal.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

